// Clipboard privacy: what's copied here that must stay here.
//
//  - A password copied from a password manager is marked "concealed" by
//    the OS convention the manager follows:
//      * macOS: the pasteboard carries `org.nspasteboard.ConcealedType`
//        (or `TransientType`, `AutoGeneratedType`; nspasteboard.org, used
//        by 1Password, Bitwarden, KeePassXC, Keychain Access…);
//      * Windows: the clipboard carries the format
//        `ExcludeClipboardContentFromMonitorProcessing`, or
//        `CanIncludeInClipboardHistory` / `CanUploadToCloudClipboard` set
//        to 0 (what Windows' own clipboard history honours);
//      * Linux: not detected. KeePassXC/KDE mark it with the MIME type
//        `x-kde-passwordManagerHint` = "secret", but arboard can't list a
//        clipboard's types, so such a copy looks like any other.
//  - A copy made while an app the user excluded is in front (macOS: its
//    bundle id, e.g. `com.agilebits.onepassword7`; Windows: its program,
//    e.g. `KeePass.exe`; Linux: not available) stays here too.
//
// Such a copy isn't synced to your other devices, isn't kept in a
// clipboard history and isn't handed to a device pulling the clipboard
// (`DesktopClipboard::keep_private` → the core). "Send clipboard" (tray,
// shortcut, quick panel, command palette) asks first, and sends it marked
// sensitive, so the phone hides it too.
//
// Settings: "Never sync passwords and other concealed clips" (on by
// default) and "Excluded apps". In `<app config dir>/prefs.json`, keys
// `clip_hide_concealed` ("on" / "off") and `clip_excluded_apps` (a JSON
// array of names).

use std::sync::{Mutex, OnceLock, RwLock};

use mdcore::kv::FileKv;
use tauri::{AppHandle, Manager};

const HIDE_KEY: &str = "clip_hide_concealed";
const APPS_KEY: &str = "clip_excluded_apps";
/// The most excluded apps kept.
const MAX_APPS: usize = 50;

/// The user's choices.
#[derive(Clone, Debug, PartialEq)]
pub struct Prefs {
    /// Never sync (or keep) a concealed copy.
    pub hide_concealed: bool,
    /// Apps whose copies stay here (bundle ids / program names).
    pub excluded: Vec<String>,
}

impl Default for Prefs {
    fn default() -> Self {
        Prefs {
            hide_concealed: true,
            excluded: Vec::new(),
        }
    }
}

/// What to do with what's on the clipboard.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Verdict {
    /// Sync it, keep it.
    Allow,
    /// Leave it here: not synced, not kept.
    Skip,
    /// Sent by hand: ask first ("This looks like a password…").
    Confirm,
}

/// Whether `app` is one of `excluded` (ignoring case and spaces around).
pub fn is_excluded(app: Option<&str>, excluded: &[String]) -> bool {
    let Some(app) = app.map(str::trim).filter(|a| !a.is_empty()) else {
        return false;
    };
    excluded.iter().any(|e| e.trim().eq_ignore_ascii_case(app))
}

/// The decision, from what the clipboard says (`concealed`), which app was
/// in front when it was copied, the user's choices, and whether the user
/// is sending it by hand (`manual`) or it would go by itself (auto-sync,
/// history).
pub fn decide(concealed: bool, app: Option<&str>, prefs: &Prefs, manual: bool) -> Verdict {
    let hidden = concealed && prefs.hide_concealed;
    match (manual, hidden) {
        (true, true) => Verdict::Confirm,
        // Sent on purpose from an excluded app: that's the user's call.
        (true, false) => Verdict::Allow,
        (false, true) => Verdict::Skip,
        (false, false) if is_excluded(app, &prefs.excluded) => Verdict::Skip,
        (false, false) => Verdict::Allow,
    }
}

/// Whether a pasteboard type is one of the nspasteboard.org markers.
#[cfg(any(target_os = "macos", test))]
pub fn concealed_type(t: &str) -> bool {
    matches!(
        t,
        "org.nspasteboard.ConcealedType"
            | "org.nspasteboard.TransientType"
            | "org.nspasteboard.AutoGeneratedType"
    )
}

/// The excluded-app list as kept: trimmed, no blanks or repeats (ignoring
/// case), at most `MAX_APPS`.
pub fn tidy(apps: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for a in apps {
        let a = a.trim().to_string();
        if !a.is_empty() && !out.iter().any(|o| o.eq_ignore_ascii_case(&a)) {
            out.push(a);
        }
    }
    out.truncate(MAX_APPS);
    out
}

struct State {
    kv: Option<FileKv>,
    prefs: RwLock<Prefs>,
    /// The app in front at the last copy (not this one).
    last_app: Mutex<Option<String>>,
}

static STATE: OnceLock<State> = OnceLock::new();

/// Read the choices; before the Engine starts.
pub fn load(app: &AppHandle) {
    let kv = app
        .path()
        .app_config_dir()
        .ok()
        .map(|dir| FileKv::new(dir.join("prefs.json")));
    let mut prefs = Prefs::default();
    if let Some(kv) = &kv {
        prefs.hide_concealed = kv.get(HIDE_KEY).as_deref() != Some("off");
        prefs.excluded = kv
            .get(APPS_KEY)
            .and_then(|j| serde_json::from_str(&j).ok())
            .map(tidy)
            .unwrap_or_default();
    }
    let _ = STATE.set(State {
        kv,
        prefs: RwLock::new(prefs),
        last_app: Mutex::new(None),
    });
}

fn prefs() -> Prefs {
    STATE
        .get()
        .and_then(|s| s.prefs.read().ok().map(|p| p.clone()))
        .unwrap_or_default()
}

/// Whether what was just copied must stay on this computer (asked by the
/// core when the clipboard changed). Notes the app in front too, for
/// "Add the app I last copied from".
pub fn keep_private_now() -> bool {
    let app = os::frontmost_app();
    if let (Some(s), Some(a)) = (STATE.get(), &app) {
        if let Ok(mut last) = s.last_app.lock() {
            *last = Some(a.clone());
        }
    }
    decide(os::concealed(), app.as_deref(), &prefs(), false) == Verdict::Skip
}

/// For "Send clipboard": whether what's copied is concealed, and whether
/// to ask before sending it.
pub fn manual_check() -> (bool, bool) {
    let concealed = os::concealed();
    let ask = decide(concealed, None, &prefs(), true) == Verdict::Confirm;
    (concealed, ask)
}

/// Ask whether to send a password anyway. Blocks: never on the main
/// thread.
pub fn confirm_send(app: &AppHandle) -> bool {
    use tauri_plugin_dialog::{DialogExt, MessageDialogButtons, MessageDialogKind};
    app.dialog()
        .message("This looks like a password copied from a password manager. Send anyway?")
        .title("Send a password?")
        .kind(MessageDialogKind::Warning)
        .buttons(MessageDialogButtons::OkCancelCustom(
            "Send anyway".into(),
            "Cancel".into(),
        ))
        .blocking_show()
}

/// The Settings section.
#[derive(serde::Serialize, specta::Type)]
pub struct ClipPrivacy {
    pub hide_concealed: bool,
    pub excluded: Vec<String>,
    /// The app in front at the last copy, if known.
    pub last_app: Option<String>,
    /// This OS can tell a concealed copy (not Linux).
    pub detects: bool,
    /// This OS can tell which app a copy came from (not Linux).
    pub knows_apps: bool,
}

#[tauri::command]
#[specta::specta]
pub fn clip_privacy() -> ClipPrivacy {
    let p = prefs();
    ClipPrivacy {
        hide_concealed: p.hide_concealed,
        excluded: p.excluded,
        last_app: STATE
            .get()
            .and_then(|s| s.last_app.lock().ok().and_then(|l| l.clone())),
        detects: cfg!(any(target_os = "macos", windows)),
        knows_apps: cfg!(any(target_os = "macos", windows)),
    }
}

fn update(f: impl FnOnce(&mut Prefs), save: impl FnOnce(&FileKv, &Prefs)) {
    let Some(s) = STATE.get() else {
        return;
    };
    let Ok(mut p) = s.prefs.write() else {
        return;
    };
    f(&mut p);
    if let Some(kv) = &s.kv {
        save(kv, &p);
    }
}

#[tauri::command]
#[specta::specta]
pub fn set_clip_hide_concealed(on: bool) {
    update(
        |p| p.hide_concealed = on,
        |kv, _| {
            if let Err(e) = kv.set(HIDE_KEY, if on { "on" } else { "off" }) {
                eprintln!("[clips] couldn't save the setting: {e}");
            }
        },
    );
}

/// Replace the excluded apps; returns them as kept.
#[tauri::command]
#[specta::specta]
pub fn set_clip_excluded_apps(apps: Vec<String>) -> Vec<String> {
    let apps = tidy(apps);
    let kept = apps.clone();
    update(
        |p| p.excluded = apps,
        |kv, p| {
            let json = serde_json::to_string(&p.excluded).unwrap_or_else(|_| "[]".into());
            if let Err(e) = kv.set(APPS_KEY, &json) {
                eprintln!("[clips] couldn't save the excluded apps: {e}");
            }
        },
    );
    kept
}

#[cfg(target_os = "macos")]
mod os {
    use objc2::msg_send;
    use objc2::rc::{autoreleasepool, Retained};
    use objc2::runtime::{AnyClass, AnyObject};
    use objc2_foundation::{NSArray, NSString};

    /// The general pasteboard's types include a concealed marker.
    pub fn concealed() -> bool {
        autoreleasepool(|_| {
            let Some(cls) = AnyClass::get(c"NSPasteboard") else {
                return false;
            };
            // SAFETY: documented NSPasteboard class/instance methods;
            // reading the general pasteboard's types is fine off the main
            // thread.
            unsafe {
                let pb: Option<Retained<AnyObject>> = msg_send![cls, generalPasteboard];
                let Some(pb) = pb else {
                    return false;
                };
                let types: Option<Retained<NSArray<NSString>>> = msg_send![&*pb, types];
                let Some(types) = types else {
                    return false;
                };
                (0..types.count())
                    .any(|i| super::concealed_type(&types.objectAtIndex(i).to_string()))
            }
        })
    }

    /// The frontmost app's bundle id, unless it's this one.
    pub fn frontmost_app() -> Option<String> {
        autoreleasepool(|_| {
            let cls = AnyClass::get(c"NSWorkspace")?;
            // SAFETY: documented NSWorkspace / NSRunningApplication methods.
            unsafe {
                let ws: Option<Retained<AnyObject>> = msg_send![cls, sharedWorkspace];
                let front: Option<Retained<AnyObject>> = msg_send![&*ws?, frontmostApplication];
                let front = front?;
                let pid: i32 = msg_send![&*front, processIdentifier];
                if u32::try_from(pid).ok() == Some(std::process::id()) {
                    return None;
                }
                let id: Option<Retained<NSString>> = msg_send![&*front, bundleIdentifier];
                id.map(|s| s.to_string())
            }
        })
    }
}

#[cfg(windows)]
mod os {
    use windows::core::{w, PWSTR};
    use windows::Win32::Foundation::{CloseHandle, HGLOBAL};
    use windows::Win32::System::DataExchange::{
        CloseClipboard, GetClipboardData, IsClipboardFormatAvailable, OpenClipboard,
        RegisterClipboardFormatW,
    };
    use windows::Win32::System::Memory::{GlobalLock, GlobalSize, GlobalUnlock};
    use windows::Win32::System::Threading::{
        GetCurrentProcessId, OpenProcess, QueryFullProcessImageNameW, PROCESS_NAME_WIN32,
        PROCESS_QUERY_LIMITED_INFORMATION,
    };
    use windows::Win32::UI::WindowsAndMessaging::{GetForegroundWindow, GetWindowThreadProcessId};

    /// The clipboard says to keep it out of monitors, the history or the
    /// cloud.
    pub fn concealed() -> bool {
        // SAFETY: plain Win32 clipboard calls; the clipboard is closed
        // again before returning, and the global memory unlocked.
        unsafe {
            let exclude =
                RegisterClipboardFormatW(w!("ExcludeClipboardContentFromMonitorProcessing"));
            if exclude != 0 && IsClipboardFormatAvailable(exclude).is_ok() {
                return true;
            }
            let flags: Vec<u32> = [
                RegisterClipboardFormatW(w!("CanIncludeInClipboardHistory")),
                RegisterClipboardFormatW(w!("CanUploadToCloudClipboard")),
            ]
            .into_iter()
            .filter(|&f| f != 0 && IsClipboardFormatAvailable(f).is_ok())
            .collect();
            if flags.is_empty() {
                return false;
            }
            // Busy (another app has it open): these flags are set almost
            // only to say 0, so take it as concealed.
            if OpenClipboard(None).is_err() {
                return true;
            }
            let mut zero = false;
            for f in flags {
                let Ok(h) = GetClipboardData(f) else {
                    continue;
                };
                let g = HGLOBAL(h.0);
                let p = GlobalLock(g) as *const u32;
                if !p.is_null() {
                    if GlobalSize(g) >= 4 && p.read_unaligned() == 0 {
                        zero = true;
                    }
                    let _ = GlobalUnlock(g);
                }
            }
            let _ = CloseClipboard();
            zero
        }
    }

    /// The foreground window's program (e.g. `KeePass.exe`), unless it's
    /// this one.
    pub fn frontmost_app() -> Option<String> {
        // SAFETY: plain Win32 calls; the process handle is closed.
        unsafe {
            let hwnd = GetForegroundWindow();
            if hwnd.is_invalid() {
                return None;
            }
            let mut pid = 0u32;
            GetWindowThreadProcessId(hwnd, Some(&mut pid));
            if pid == 0 || pid == GetCurrentProcessId() {
                return None;
            }
            let h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, false, pid).ok()?;
            let mut buf = [0u16; 1024];
            let mut len = buf.len() as u32;
            let ok = QueryFullProcessImageNameW(
                h,
                PROCESS_NAME_WIN32,
                PWSTR(buf.as_mut_ptr()),
                &mut len,
            )
            .is_ok();
            let _ = CloseHandle(h);
            if !ok {
                return None;
            }
            let path = String::from_utf16_lossy(&buf[..len as usize]);
            path.rsplit(['\\', '/']).next().map(str::to_string)
        }
    }
}

/// Linux: arboard can't list the clipboard's types, nor is there one
/// frontmost app across X11/Wayland; see the top of this file.
#[cfg(not(any(target_os = "macos", windows)))]
mod os {
    pub fn concealed() -> bool {
        false
    }
    pub fn frontmost_app() -> Option<String> {
        None
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn prefs(hide: bool, apps: &[&str]) -> Prefs {
        Prefs {
            hide_concealed: hide,
            excluded: apps.iter().map(|a| a.to_string()).collect(),
        }
    }

    #[test]
    fn a_concealed_copy_stays_here_and_asks_before_a_manual_send() {
        let p = prefs(true, &[]);
        assert_eq!(decide(true, None, &p, false), Verdict::Skip);
        assert_eq!(decide(true, None, &p, true), Verdict::Confirm);
        assert_eq!(decide(false, None, &p, false), Verdict::Allow);
        assert_eq!(decide(false, None, &p, true), Verdict::Allow);
    }

    #[test]
    fn with_the_setting_off_a_concealed_copy_goes_like_any_other() {
        let p = prefs(false, &[]);
        assert_eq!(decide(true, None, &p, false), Verdict::Allow);
        assert_eq!(decide(true, None, &p, true), Verdict::Allow);
    }

    #[test]
    fn copies_from_an_excluded_app_are_not_synced_but_can_be_sent() {
        let p = prefs(true, &["com.agilebits.onepassword7", "KeePass.exe"]);
        let one = Some("com.agilebits.onepassword7");
        assert_eq!(decide(false, one, &p, false), Verdict::Skip);
        assert_eq!(decide(false, Some("keepass.EXE"), &p, false), Verdict::Skip);
        assert_eq!(
            decide(false, Some("com.apple.Safari"), &p, false),
            Verdict::Allow
        );
        assert_eq!(decide(false, None, &p, false), Verdict::Allow);
        assert_eq!(decide(false, one, &p, true), Verdict::Allow);
        // Excluded apps apply even with the concealed setting off.
        let off = prefs(false, &["KeePass.exe"]);
        assert_eq!(
            decide(false, Some("KeePass.exe"), &off, false),
            Verdict::Skip
        );
    }

    #[test]
    fn only_the_nspasteboard_markers_are_concealed() {
        assert!(concealed_type("org.nspasteboard.ConcealedType"));
        assert!(concealed_type("org.nspasteboard.TransientType"));
        assert!(concealed_type("org.nspasteboard.AutoGeneratedType"));
        assert!(!concealed_type("public.utf8-plain-text"));
        assert!(!concealed_type("org.nspasteboard.source"));
    }

    #[test]
    fn the_app_list_is_tidied() {
        let got = tidy(vec![
            " KeePass.exe ".into(),
            "".into(),
            "keepass.exe".into(),
            "com.bitwarden.desktop".into(),
        ]);
        assert_eq!(got, ["KeePass.exe", "com.bitwarden.desktop"]);
        assert!(!is_excluded(Some("  "), &got));
    }
}
